import org.gradle.api.JavaVersion

/** Mirrors exactly what the gradle.kts task would do. */
fun flutterMinJavaMajor(): Int {
    val cls = Class.forName("com.flutter.gradle.DependencyVersionChecker")
    val instance = cls.getField("INSTANCE").get(null)
    // Kotlin `internal` compiles to a public JVM getter with a `$<module>` suffix.
    // Match by prefix so an upstream module rename does not break us.
    val getter = cls.methods.firstOrNull {
        it.parameterCount == 0 &&
            (it.name == "getErrorJavaVersion" || it.name.startsWith("getErrorJavaVersion$"))
    } ?: error(
        "Could not find errorJavaVersion getter on DependencyVersionChecker. " +
            "Available: " + cls.methods.map { it.name }.sorted()
    )
    val version = getter.invoke(instance) as JavaVersion
    return version.majorVersion.toInt()
}

